filenames = {_decode(row['SPECT_ID']): _decode(row['Filename']) for row in Table.read(CATALOG_PATH)}
for target in manifest['targets']:
    target['filename'] = filenames[target['spect_id']]
print(json.dumps(manifest))
"""
